<template><div class="page"><div class="page-header"><h2>设备变更</h2></div><el-card shadow="never"><el-table :data="items" v-loading="loading" stripe size="small" highlight-current-row @row-click="open"><el-table-column prop="device_change_id" label="变更单号" width="120"/><el-table-column label="变更类型" width="90"><template #default="{row}">{{ ktLabel(row.change_type) }}</template></el-table-column><el-table-column label="状态" width="80"><template #default="{row}"><el-tag :type="statusTag(row.current_status)" size="small">{{ statusLabel(row.current_status) }}</el-tag></template></el-table-column><el-table-column label="负责人" width="80"><template #default="{row}">{{ userName(row.firstor) }}</template></el-table-column><el-table-column label="创建日期" width="100"><template #default="{row}">{{ row.create_time || '-' }}</template></el-table-column><el-table-column label="完成日期" width="100"><template #default="{row}">{{ row.close_time || '-' }}</template></el-table-column></el-table>
    <el-dialog :title="'设备变更 — '+(detail?.device_change_id||'')" v-model="drawer" width="500px"><template v-if="detail"><el-descriptions :column="2" border size="small"><el-descriptions-item label="单号">{{ detail.device_change_id }}</el-descriptions-item><el-descriptions-item label="变更类型">{{ ktLabel(detail.change_type) }}</el-descriptions-item><el-descriptions-item label="状态">{{ detail.current_status }}</el-descriptions-item><el-descriptions-item label="负责人">{{ userName(detail.firstor) }}</el-descriptions-item><el-descriptions-item label="创建时间">{{ detail.create_time }}</el-descriptions-item><el-descriptions-item label="完成时间">{{ detail.close_time||'-' }}</el-descriptions-item></el-descriptions></template></el-dialog><AppPagination v-model:current-page="page" v-model:page-size="perPage" :total="total" style="margin-top:12px;justify-content:flex-end"/></el-card></div></template>
<script setup lang="ts">import AppPagination from '@/components/common/AppPagination.vue';import {useListPage} from '@/composables/useListPage';import {useDetailDrawer} from '@/composables/useDetailDrawer';import {useUserNames} from '@/composables/useUserNames';import {fetchDeviceChange} from '@/api/itsm';import type {MntRecord} from '@/api/itsm';import {useDict} from '@/composables/useDict'
const{items,loading,page,perPage,total}=useListPage<MntRecord>(fetchDeviceChange);const{drawer,detail,open}=useDetailDrawer<MntRecord>();const{userName}=useUserNames()
const{dictLabel:ktLabel}=useDict('PL')
function statusTag(s:string){const m:Record<string,string>={'1':'info','2':'primary','3':'success','4':'warning','5':'primary','9':'danger'};return m[s]||'info'}
function statusLabel(s:string){const m:Record<string,string>={'1':'新建','2':'分配','3':'关闭','4':'未解决','5':'已解决','9':'作废'};return m[s]||s}</script>
<style scoped>.page{padding:0}.page-header{display:flex;justify-content:space-between;margin-bottom:16px}.page-header h2{font-size:18px;font-weight:600;margin:0}</style>